// game initialization
let backgroundImages = [assets.image`background0`, assets.image`background1`, assets.image`background2`, assets.image`background3`]
let pathTiles = [assets.tile`pathTile0`, assets.tile`pathTile1`, assets.tile`pathTile2`, assets.tile`pathTile3`]
let spriteImages = [assets.image`spriteImage0`]

let currentIndex = 0
let currentTile = pathTiles[currentIndex]

// game start
scene.setBackgroundImage(backgroundImages[currentIndex])
tiles.setCurrentTilemap(assets.tilemap`roadTilemap`)

let mySprite = sprites.create(spriteImages[currentIndex], SpriteKind.Player)
tiles.placeOnTile(mySprite, tiles.getTileLocation(4, 6))

function changeScene(newIndex: number) {
    mySprite.setImage(spriteImages[newIndex])
    scene.setBackgroundImage(backgroundImages[newIndex])
    for (let element of tiles.getTilesByType(currentTile)) {
        tiles.setTileAt(tiles.getTileLocation(element.column, element.row), pathTiles[newIndex])
    }
}

// game events
controller.B.onEvent(ControllerButtonEvent.Pressed, function () {
    currentIndex++
    changeScene(currentIndex)
})

